def match_parens(lst):
    if len(lst) != 2 or not all(isinstance(s, str) for s in lst):
        return 'No'

    for s in lst:
        if not all(c in ['(', ')'] for c in s):
            return 'No'

    def is_balanced(s):
        stack = []
        for char in s:
            if char == '(':
                stack.append(char)
            elif char == ')':
                if not stack:
                    return False
                stack.pop()
        return len(stack) == 0

    def can_concatenate(s1, s2):
        return is_balanced(s1 + s2) or is_balanced(s2 + s1)

    if can_concatenate(lst[0], lst[1]):
        return 'Yes'
    else:
        return 'No'

